// El panel manda { action, sessionId, chatInput } dentro de "body". Se comprueba antes de gastar saldo del modelo.
const body = ($input.first().json.body) || {};
const chatInput = typeof body.chatInput === 'string' ? body.chatInput.trim() : '';
const sessionId = typeof body.sessionId === 'string' ? body.sessionId.trim() : '';
if (!chatInput) throw new Error('Falta el mensaje (chatInput).');
if (chatInput.length > 4000) throw new Error('El mensaje supera los 4000 caracteres.');
if (!/^[A-Za-z0-9-]{8,64}$/.test(sessionId)) throw new Error('El sessionId no es válido.');
return [{ json: { chatInput, sessionId } }];
